fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    str1.iter()
        .map(|&c| {
            if c >= 'a' && c <= 'z' {
                // Convert to uppercase by offsetting the ASCII value by 32
                // The difference between 'a' and 'A' is 32
                ((c as u8) - 32) as char
            } else {
                c
            }
        })
        .collect()
}